"""Generate the Raze rules shared by the native controller and browser lab."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
def write_rules(path,text):
 # Identical generated Rust must not invalidate both native and WASM builds.
 if not path.exists() or path.read_text(encoding='utf-8')!=text:path.write_text(text,encoding='utf-8')
d=json.loads((ROOT/'rules/raze.json').read_text(encoding='utf-8'))
lines=['// Generated by tools/generate-raze.py. Edit rules/raze.json.',
       f'pub const TPS: i64 = {d["ticks_per_second"]};',
       'pub const RULES_REVISION: &str = '+json.dumps(d['rules_revision'])+';']
lines += [f'pub const {k}: i64 = {v};' for k,v in d['constants'].items()]
# Air strafe limit as integer millis, so native and WASM share it without runtime trigonometry.
import math
strafe=math.radians(d['constants']['AIR_STRAFE_MAX_DEG'])
lines += [f'pub const AIR_STRAFE_COS: i64 = {round(math.cos(strafe)*1000)};',f'pub const AIR_STRAFE_SIN: i64 = {round(math.sin(strafe)*1000)};']
write_rules(ROOT/'native/tfm2_custom_ai/src/raze_data.rs','\n'.join(lines)+'\n')
(ROOT/'editor/raze-data.js').write_text('/* Generated by tools/generate-raze.py */\nwindow.RAZE_RULES='+json.dumps(d,separators=(',',':'))+';\n',encoding='utf-8')
gunlines=['// Generated by tools/generate-raze.py from the shared Omen/Raze weapon table.']
for key,field in [('PRICES','price'),('RANGES','range'),('ATTACK_MODIFIERS','attack_modifier'),('SPEED_MODIFIERS','speed_modifier'),('TIERS','tier')]:
 gunlines.append(f'const {key}: [i64; {len(d["weapons"])}] = '+json.dumps([g[field] for g in d['weapons']])+';')
for group in ['judge','bucky']:
 for key,value in d[group].items():gunlines.append(f'pub const {group.upper()}_{key.upper()}: i64 = {value};')
write_rules(ROOT/'native/tfm2_custom_ai/src/valorant_gun_data.rs','\n'.join(gunlines)+'\n')
print('Raze native/editor rules generated')

# Champion action shells follow Omen's existing native-owned convention.
omen=json.loads((ROOT/'mods/tfm2_valorant/champion/tfm2_valorant_omen.data_champion').read_text(encoding='utf-8'))
champ=json.loads(json.dumps(omen));champ['id']=d['identity']['id'];champ['category']='Range';champ['tags']=d['identity']['tags'];champ['sprite']='asset/tfm2_valorant/champions/tfm2_valorant_raze';champ['passive']={'passive_ref':'tfm2_custom_ai:raze','params':{}}
for key in ['stat','growth']:champ[key].update(d['stats' if key=='stat' else 'growth'])
for slot in ['skill','skill2','ult']:champ[slot]['description']='#asset/base/text/champion?description.tfm2_valorant_raze.'+slot
champ['view_buffs']=[v for v in omen.get('view_buffs',[]) if v.get('name','').startswith(('omn_gun','omn_arm','omn_cr','omn_cash'))];champ['view_effects']=[]
bucky=json.loads(json.dumps(next(v for v in omen['view_buffs'] if v['name']=='omn_gun3')))
bucky.update(name='omn_gun6',anim='asset/tfm2_valorant/vfx/raze',tag='gun_bucky');champ['view_buffs'].append(bucky)
for tag in ['grenade_prep','pack_throw','bot_prep','rocket_equip','rocket_ready','rocket_release','buy','grenade_warning','cluster_warning','bot_warning','rocket_path','satchel_blast','grenade_blast','cluster_blast','rocket_blast','landing','grenade_flight','rocket_flight','satchel','bot']:
 champ['view_effects'].append(dict(type='Animation',name='tfm2_valorant_raze_'+tag,anim='asset/tfm2_valorant/vfx/raze',tag=tag,z=5,is_follow=tag in ['satchel','bot','buy']))
for direction in range(8):champ['view_effects'].append(dict(type='Animation',name='tfm2_valorant_raze_rocket_flight_'+str(direction),anim='asset/tfm2_valorant/vfx/raze',tag='rocket_flight_'+str(direction),z=5,is_follow=False))
for v in champ['view_effects']:
 if v['name']=='tfm2_valorant_raze_rocket_blast':v['tag']='rocket_blast_large'
 for old in ['satchel_blast','grenade_blast','grenade_warning','cluster_blast','cluster_warning']:
  if v['name']=='tfm2_valorant_raze_'+old:v['tag']=old+'_wide'
champ['view_effects'].append(dict(type='Animation',name='tfm2_valorant_raze_rocket_impact_warning',anim='asset/tfm2_valorant/vfx/raze',tag='rocket_impact_warning',z=5,is_follow=False))
for tag in ['satchel_ground','satchel_north','satchel_east','satchel_south','satchel_west']+[f'rocket_impact_warning_{n}' for n in range(8)]+[f'bot_round_{n}' for n in range(8)]:
 champ['view_effects'].append(dict(type='Animation',name='tfm2_valorant_raze_'+tag,anim='asset/tfm2_valorant/vfx/raze',tag=tag,z=5,is_follow=tag.startswith(('satchel_','bot_round_'))))
# Visuals renewed every tick select one baked frame (1/60 s), so a renewal never stacks a 24-tick copy.
PHASED=[('grenade_flight','grenade_flight'),('grenade_warning','grenade_warning_wide')]+[(f'rocket_flight_{n}',)*2 for n in range(8)]+[(t,t) for t in ['satchel_ground','satchel_north','satchel_east','satchel_south','satchel_west']]+[(f'bot_round_{n}',)*2 for n in range(8)]
for name,tag in PHASED:
 for k in range(8):champ['view_effects'].append(dict(type='Animation',name=f'tfm2_valorant_raze_{name}_p{k}',anim='asset/tfm2_valorant/vfx/raze',tag=f'{tag}_p{k}',z=5,is_follow=name.startswith(('satchel_','bot_round_'))))
# Reuse Omen's gun and credit indicators exactly; the asset belongs to the same pack.
for view in omen.get('view_effects',[]):
 if any(t in view.get('name','') for t in ['gun','money','credit','tracer','pellets','op_flash']):
  v=json.loads(json.dumps(view));v['name']=v['name'].replace('tfm2_valorant_omen','tfm2_valorant_raze');champ['view_effects'].append(v)
# Same purchase feedback as Omen, using the existing pixels and timing.
buy=next(v for v in omen['view_effects'] if v['name']=='tfm2_valorant_omen_buy')
buy=json.loads(json.dumps(buy));buy['name']='tfm2_valorant_raze_buy'
champ['view_effects']=[buy if v['name']==buy['name'] else v for v in champ['view_effects']]
for variant in ['','_rocket','_grenade','_pack']:
 for facing in ['r','l']:champ['view_effects'].append(dict(type='Animation',name='tfm2_valorant_raze_airborne'+variant+'_'+facing,anim=champ['sprite'],tag='airborne'+variant+'_'+facing,z=6,is_follow=False))
# Round 144: the ultimate unlocks through the ult_learned marker (as Gojo, Magnus and Unified), a larger rocket, and
# her new kit's effects and HUD (Hype bar, Carnaval aura, the air shield drawn with Omen's armour icon).
champ['passive_ult']={'passive_ref':'tfm2_custom_ai:ult_learned','params':{}}
for tag in ['rocket_ready_big','graffiti','encore','carnaval','combustion','rocket_scorch','burn_zone']+[f'rocket_flight_big_{d}_p{k}' for d in range(8) for k in range(8)]:
 champ['view_effects'].append(dict(type='Animation',name='tfm2_valorant_raze_'+tag,anim='asset/tfm2_valorant/vfx/raze',tag=tag,z=5,is_follow=False))
for name,anim,tag in [(f'rz_hype{n}','raze',f'hype_{n}') for n in range(1,6)]+[('rz_carnaval','raze','carnaval_aura'),('rz_air_shield','valorant','arm_2')]:
 champ['view_buffs'].append(dict(type='Animated',name=name,anim='asset/tfm2_valorant/vfx/'+anim,tag=tag,z=3))
C=d['constants']
def sec(t):return f"{t/60:g}"
text={
 'name':'Raze',
 'skill':f"Paint Shells: cluster grenade. Buy Phase, as Omen: one free charge returns every {sec(C['GRENADE_COOLDOWN'])} seconds and a second charge costs {C['GRENADE_PRICE']} credits. {C['GRENADE_RANGE']} throw range. Main blast {C['GRENADE_DAMAGE']} + {C['GRENADE_ATTACK']}% Attack, then four smaller blasts ({C['CLUSTER_DAMAGE']} + {C['CLUSTER_ATTACK_NUM']*100/C['CLUSTER_ATTACK_DEN']:g}% Attack), at most two secondary hits per enemy. Boom Bot is an additional native ability: one free charge every {sec(C['BOT_COOLDOWN'])} seconds, a second for {C['BOT_PRICE']} credits, one destructible bot, {C['BOT_DAMAGE']} + {C['BOT_ATTACK']}% Attack blast. Grenade/rocket self-damage is {C['SELF_DAMAGE_PERCENT']}% before mitigation. Omen's weapon progression, prices, gun-first buying, armour rule and credit income; bought charges are lost on death and free charges return at once, weapons persist. No mastery. All 13 pinned athlete attributes influence decisions and execution only.",
 'skill2':f"Blast Pack: one free charge returns every {sec(C['PACK_COOLDOWN'])} seconds and a second costs {C['PACK_PRICE']} credits, as Omen's second smoke. Detonate to add a radial launch impulse; air-strafe with bounded directional acceleration, steering at most {C['AIR_STRAFE_MAX_DEG']} degrees from the flight heading (she turns instead of reversing), and retained momentum. A second satchel adds another impulse. Armed after {sec(C['PACK_ARM'])} seconds: {C['PACK_DAMAGE']} + {C['PACK_ATTACK']}% Attack and enemy knockback within {C['PACK_RADIUS']}. Satchels have {C['PACK_HP']} HP and expire after {sec(C['PACK_LIFETIME'])} seconds without exploding. Raze stays targetable. Terrain, roots and movement-blocks constrain travel.",
 'ult':f"Showstopper: ultimate unlock required; equip for {sec(C['ROCKET_PREP'])} seconds and fire within {sec(C['ROCKET_LIFETIME'])} seconds. Cooldown {sec(C['ROCKET_COOLDOWN'])} seconds from firing; an equip that is interrupted or never fired costs nothing. Ground endpoint or first unit/wall impact. Maximum {C['ROCKET_DAMAGE']} + {C['ROCKET_ATTACK']}% Attack; continuous falloff to 25% at {C['ROCKET_RADIUS']} radius. Travel up to {C['ROCKET_RANGE']} starting at {C['ROCKET_START_SPEED']} and accelerating to {C['ROCKET_SPEED']} units/second over 0.3 seconds. Firing gives a short grounded recoil slide or an airborne third boost opposite the shot. Actual airborne flight grants {C['AIR_REDUCTION']}% damage reduction; ground recoil does not. Grenade/rocket self-damage remains {C['SELF_DAMAGE_PERCENT']}% before normal mitigation. No homing, free charges or animation-cancel skips."}
text['skill2']+=f" Actual airborne flight grants {C['AIR_REDUCTION']}% incoming damage reduction, lingering after landing or interruption for 3/5.25/7.5/9.75/12 seconds with 1/2/3/4/5+ visible enemy champions within 80000; none nearby grants no extension; death clears it; no crowd-control immunity. Judge now deals 3x basic damage through 10000, falling to 0.7x at 20000; Raze buys it, as Omen does, against two or more close fighters."
text['skill']+=f" Main radius {C['GRENADE_RADIUS']}; four cluster centres scatter diagonally by {C['CLUSTER_OFFSET']} per axis, each with {C['CLUSTER_RADIUS']} radius."
text['skill2']+=f" Packs stick to ground, wall faces and solid constructions. Launch impulse {C['LAUNCH_SPEED']}; air acceleration {C['AIR_ACCEL']}, preserving momentum and speed caps."
text['ult']+=' Warns the predicted impact area; enemies attempt to escape. Surviving enemy champions, minions and summons are pushed outward over 0.2 seconds, with terrain and immunity respected.'
text['skill']+=f" Grenades reflect off solid walls and map edges; the warning follows their actual landing. Boom Bot rolls along the thrown direction, bounces off walls, and acquires visible enemies in its forward cone within {C['BOT_SIGHT']} units, retaining that visible target within {C['BOT_TRACK_RANGE']}."
for slot in ['skill','skill2','ult']:
 text[slot]+=' These skills deal physical damage. Enemy skill damage is exactly 3x the original integer result after Attack scaling and falloff, before armour. Self-damage retains the original unbuffed formula. Mod Power, weapon bonuses and item Attack are read once through current stats.'
text['skill']=text['skill'].replace("Omen's weapon progression, prices, gun-first buying, armour rule and credit income", "Free starting Bucky and 1000 credits; save for a useful Judge or Vandal upgrade before buying extra utility or armour, with Omen's credit income")
text['skill2']=text['skill2'].replace('Raze buys it, as Omen does, against two or more close fighters','Raze saves for it when a close entry is viable; otherwise she saves for Vandal')
text['skill2']+=' Q / Place launch satchel drops directly under the caster when placement completes; aimed throws remain available. Blast and launch radius 56000. Domed launch: the centre adds lift only and keeps existing horizontal velocity. At 14000 offset, launch outward at 200000 with 48 ticks of fresh airtime; force fades to zero at the 56000 edge. Air acceleration is 600000. Landing defence snapshots champions once, never stacks, and later arrivals do not refresh it. Bucky: 18000 range, 300% AD through 8000 falling linearly to 60% at 18000, -40% weapon attack speed, physical primary attack with shotgun splash. Offensive AI entries require survival and champion follow-up or an exit; manual commands keep normal mechanical freedom.'
# Round 144: her MOBA kit. The Bucky sentence follows the shared table; mastery replaces "No mastery".
B=d['bucky'];bucky=next(w for w in d['weapons'] if w['name']=='Bucky')
text['skill2']=text['skill2'].replace('Bucky: 18000 range, 300% AD through 8000 falling linearly to 60% at 18000',f"Bucky: {bucky['range']} range, {B['near_percent']}% AD through {B['near_range']} falling linearly to {B['far_percent']}% at {B['far_range']}")
text['skill']=text['skill'].replace('No mastery.',f"Mastery {' / '.join(d['mastery'])} comes from the athlete's games on Raze and sharpens only aim, timing and Hype use.")
text['skill']+=(f" Hype: champion hits +{C['HYPE_CHAMPION_HIT']}, minion or camp hits +{C['HYPE_UNIT_HIT']}, launches +{C['HYPE_LAUNCH']}, takedowns +{C['HYPE_TAKEDOWN']}; it fades out of combat. At {C['HYPE_MAX']} she bursts into Carnaval for {sec(C['CARNAVAL_TICKS'])} seconds: skill cooldowns recover twice as fast, +{C['CARNAVAL_SPEED']}% move speed, a doubled air shield and an extra cluster."
 f" Graffiti: the main blast leaves paint for {sec(C['GRAFFITI_TICKS'])} seconds that slows enemies {C['GRAFFITI_SLOW']}% and makes them take {C['GRAFFITI_AMPLIFY']}% more from her. Paint Shells clears waves of {C['GRENADE_FARM_MIN']}+ minions; clusters deal +{C['CLUSTER_FARM_PERCENT']-100}% to minions and camps."
 f" Hot Hands: a takedown or {C['HOT_HANDS_HITS']} main-blast champion hits return the free charge. Combustion: {C['BURN_STACKS']} skill hits on a champion deal {C['BURN_MAX_HP_PERCENT']}% of their max HP as true damage and reveal them for {sec(C['BURN_REVEAL_TICKS'])} seconds."
 f" Boom Bot hunts the nearest wave, camp or structure when no champion is in sight and deals +{C['BOT_STRUCTURE_PERCENT']-100}% to structures and objectives; its hit Primes a champion, so her next Paint Shells or Showstopper deals +{C['PRIMED_PERCENT']}% to them within {sec(C['PRIMED_TICKS'])} seconds."
 f" Skills gain {C['SKILL_LEVEL_BASE']} base damage per level and heal her for {C['OMNIVAMP']}% of what they deal ({C['OMNIVAMP_PROTECTED']}% against champions while landing defence or the air shield is up). Kills pay +{C['KILL_BOUNTY']} credits; takedowns restore {C['TAKEDOWN_ARMOR_PERCENT']}% armour. Still on the Bucky at level {C['FREE_SHERIFF_LEVEL']}, she gets a free Sheriff."
 f" Bucky alternate fire: a slug at one target up to {C['SLUG_RANGE']} for {C['SLUG_ATTACK']}% AD every {sec(C['SLUG_COOLDOWN'])} seconds, used beyond {C['SLUG_MIN_RANGE']} while she is safe.")
text['skill2']+=(f" Air shield: each launch tops up a shield of {C['AIR_SHIELD_HP_PERCENT']}% max HP + {C['AIR_SHIELD_ATTACK']}% Attack that lasts the flight and lingers for the landing-defence window; one shield at a time."
 f" Encore: her first landing after {C['ENCORE_EXPLOSIONS']} explosions within {sec(C['ENCORE_WINDOW'])} seconds sends a {C['ENCORE_RADIUS']} shockwave ({C['ENCORE_ATTACK']}% Attack, {sec(C['ENCORE_LIFT_TICKS'])}-second knock-up), every {sec(C['ENCORE_COOLDOWN'])} seconds."
 f" Satchel combo: an enemy pushed into a Paint Shells blast within {sec(C['COMBO_WINDOW'])} second is stunned {sec(C['COMBO_STUN'])} seconds. A takedown within {sec(C['RESET_WINDOW'])} seconds of her damage returns the free Blast Pack charge.")
text['ult']+=(f" The ultimate unlocks with the game's learned-ultimate marker. She holds the armed pose {sec(C['ROCKET_HOLD'])} seconds before an AI shot. The impact scorches the ground and burns for {sec(C['BURN_ZONE_TICKS'])} seconds ({C['BURN_ZONE_RADIUS']} radius, {C['BURN_ZONE_ATTACK']}% Attack each second); each champion takedown refunds {C['ULT_TAKEDOWN_REFUND']}% of the cooldown.")
(ROOT/'mods/tfm2_valorant/champion/tfm2_valorant_raze.data_champion').write_text(json.dumps(champ,indent=2)+'\n',encoding='utf-8')
path=ROOT/'mods/tfm2_valorant/text/champion.i18n';loc=json.loads(path.read_text(encoding='utf-8'));loc['en']['description']['tfm2_valorant_raze']=text
for slot,value in loc['en']['description']['tfm2_valorant_omen'].items():loc['en']['description']['tfm2_valorant_omen'][slot]=value.replace('2.2x point blank','3x point blank')
path.write_text(json.dumps(loc,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
(ROOT/'editor/raze-preset.js').write_text('window.RAZE_PRESET='+json.dumps(champ,separators=(',',':'))+';\nwindow.RAZE_TEXT='+json.dumps(text,separators=(',',':'))+';\n',encoding='utf-8')
path=ROOT/'rules/champions.json';roster=json.loads(path.read_text(encoding='utf-8'));roster['champions']=[c for c in roster['champions'] if c['id']!='tfm2_valorant_raze']
roster['champions'].append(dict(id='tfm2_valorant_raze',name='Raze',family='valorant',role='Range',native=True,basicAttack=dict(name='Bucky / purchased gun',kind='ranged',range=bucky['range']),skills=[
 dict(slot='skill',name='Paint Shells / Boom Bot',kinds=['Projectile','Aoe','Summon'],intents=['Clear','Poke','Objective','Vision'],summary="Cluster grenade that paints the ground (slow, +10% damage taken) or a bot that hunts waves when no champion is near: one free charge each on its cooldown, a second bought like Omen's smoke. Hits build Hype toward Carnaval."),
 dict(slot='skill2',name='Blast Pack',kinds=['Dash','Aoe','Cc'],intents=['Engage','Escape','Protect'],summary='Satchels for momentum launches and limited air strafing (155° max turn): one free charge on a 6 s cooldown, a second bought; armed packs displace enemies (into paint: a short stun). Launches grant a lingering air shield; Encore knocks up on landing.'),
 dict(slot='ult',name='Showstopper',kinds=['Projectile','Aoe'],intents=['Engage','Poke','Objective'],summary='Equip one warned rocket; fixed flight, area falloff and reduced self-damage. The cooldown starts when it fires. Can combine with satchel entries. Leaves a burning zone; takedowns refund part of the cooldown.')]))
path.write_text(json.dumps(roster,ensure_ascii=False,indent=1)+'\n',encoding='utf-8')
